# 판정 → 아이콘 이름 (채움). 모양이 넷 다 다르다: 체크 원 · 경고 삼각 · 금지 원 · 물음표 원
VERDICT_ICONS: dict[str, str] = {"가능": "check_circle", "조건부": "warning", "불가": "block", "판단보류": "help"}


def _check(name: str) -> None:
    if name not in ICON_PATHS:
        raise ValueError(f"알 수 없는 아이콘 '{name}'. 쓸 수 있는 이름: {', '.join(sorted(ICON_PATHS))}")


def svg_markup(name: str, color: str = "#000000") -> str:
    """아이콘 하나의 SVG 문서 문자열 (마스크·이미지·파일 저장용)."""
    _check(name)
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{VIEWBOX}">'
        f'<path fill="{color}" d="{ICON_PATHS[name]}"/></svg>'
    )


def data_uri(name: str, color: str = "#000000") -> str:
    """아이콘 SVG 의 base64 data URI. CSS url() 이나 <img src> 에 그대로 쓴다."""
    encoded = base64.b64encode(svg_markup(name, color).encode("utf-8")).decode("ascii")
    return f"data:image/svg+xml;base64,{encoded}"


def _mask_uri(name: str) -> str:
    """마스크용 data URI. 모양(알파)만 쓰므로 색이 없고, base64 보다 짧은 URL 인코딩을 쓴다."""
    svg = f"<svg xmlns='http://www.w3.org/2000/svg' viewBox='{VIEWBOX}'><path d='{ICON_PATHS[name]}'/></svg>"
    return "data:image/svg+xml," + quote(svg, safe="/:='-., ")


@lru_cache(maxsize=1)
def icon_css() -> str:
    """.bw-i--이름 마스크 규칙 전부. theme.inject_base_css() 가 base.css 뒤에 붙여 넣는다."""
    rules = [f'.bw-i--{name}{{--bw-i:url("{_mask_uri(name)}")}}' for name in ICON_PATHS]
    return "\n".join(rules)


def icon(name: str, size: int = 20, color: str | None = None, *, label: str | None = None, cls: str = "") -> str:
    """아이콘 span 한 개.

    name  : ICON_PATHS 의 이름. 모르는 이름이면 ValueError (오타를 바로 드러낸다).
    size  : 한 변 px.
    color : CSS 색 ("#D2263F", "var(--bw-no-solid)"). None 이면 부모 글자색을 따른다.
    label : 의미가 있는 아이콘이면 읽어 줄 이름. None 이면 장식(aria-hidden).
    cls   : 덧붙일 클래스.
    """
    _check(name)
    style = f"--bw-i-size:{int(size)}px" + (f";color:{html.escape(color, quote=True)}" if color else "")
    aria = f'role="img" aria-label="{html.escape(label, quote=True)}"' if label else 'aria-hidden="true"'
    extra = f" {html.escape(cls, quote=True)}" if cls else ""
    return f'<span class="bw-i bw-i--{name}{extra}" style="{style}" {aria}></span>'


def icon_img(name: str, size: int = 20, color: str = "#1D1846", *, label: str = "") -> str:
    """CSS 없이도 보이는 <img> 아이콘 (base.css 가 없는 곳에 내보낼 때만). 색은 고정된다."""
    alt = html.escape(label, quote=True)
    return f'<img src="{data_uri(name, color)}" width="{int(size)}" height="{int(size)}" alt="{alt}">'
